import yt_dlp, urllib.request, io, os, math, colorsys
from PIL import Image

def fetch(url):
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=25).read()

def tile_mean(t):
    w,h = t.size
    p = t.load()
    rs=gs=bs=0
    for y in range(0,h,2):
        for x in range(0,w,2):
            r,g,b=p[x,y]; rs+=r; gs+=g; bs+=b
    n=((h+1)//2)*((w+1)//2)
    return (rs/n, gs/n, bs/n)

def is_pad(c):
    return max(c)-min(c) < 4 and 100 <= (c[0]+c[1]+c[2])/3 <= 155

def get_sequence(vid):
    opts = {'quiet': True, 'no_warnings': True, 'skip_download': True, 'socket_timeout': 25,
            'format': 'sb2/best', 'extractor_args': {'youtube': {'player_client': ['web_safari']}}}
    with yt_dlp.YoutubeDL(opts) as ydl:
        info = ydl.extract_info(f"https://www.youtube.com/watch?v={vid}", download=False)
    dur = info.get('duration')
    sbs = [f for f in info['formats'] if f.get('format_id','').startswith('sb')]
    for fid in ['sb0','sb1','sb2']:
        f=[x for x in sbs if x['format_id']==fid]
        if f: sb=f[0]; break
    url0=sb['url']; cols=sb.get('columns',5); rows=sb.get('rows',5)
    seq=[]; sheet=0
    while True:
        try: data=fetch(url0.replace('$M',str(sheet)))
        except Exception: break
        im=Image.open(io.BytesIO(data)).convert('RGB')
        W,Hh=im.size
        for r in range(rows):
            for c in range(cols):
                t=im.crop((c*W//cols, r*Hh//rows, (c+1)*W//cols, (r+1)*Hh//rows)).resize((32,18))
                seq.append(tile_mean(t))
        sheet+=1
        if sheet>15: break
    while seq and is_pad(seq[-1]): seq.pop()
    while seq and is_pad(seq[0]): seq.pop(0)
    return dur, seq

names={"60ItHLz5WEA":"I Faded","UprcpdwuwCg":"F Heathens","lWA2pjMjpBs":"C Diamonds","papuvlVeZg8":"B Rockabye",
"pXRviuL6vMY":"E Stressed Out","IcrbM1l_BoI":"H Wake Me Up","kOkQ4T5WO9E":"G TIWYCF","e-ORhEE9VVg":"J Blank Space",
"KQ6zr6kCPj8":"D Party Rock","FM7MFYoylVs":"A SJLT"}

# barcode V profile
im = Image.open('barcode.png').convert('RGB')
W,H=im.size; px=im.load()
bV=[]
for x in range(W):
    v=0
    for y in range(H):
        r,g,b=px[x,y]; v+= (r+g+b)/3
    bV.append(v/H)

def pearson(a,b):
    n=len(a); ma=sum(a)/n; mb=sum(b)/n
    ca=[x-ma for x in a]; cb=[x-mb for x in b]
    num=sum(x*y for x,y in zip(ca,cb))
    den=math.sqrt(sum(x*x for x in ca)*sum(y*y for y in cb))
    return num/den if den else 0

print(f"{'video':<15} {'Vcorr':>7} {'S-corrupt?':>10}   meanSeqV  meanBarV")
res=[]
for vid,name in names.items():
    try:
        dur, seq = get_sequence(vid)
        N=len(seq)
        # candidate brightness resampled to 1000 cols by time
        cV=[ sum(t)/3 for t in seq ]
        rV=[ cV[min(N-1,int(x/W*N))] for x in range(W) ]
        corr=pearson(bV, rV)
        res.append((corr, name, sum(cV)/N, sum(bV)/W))
        print(f"{name:<15} {corr:7.3f}              {sum(cV)/N:8.1f}  {sum(bV)/W:8.1f}")
    except Exception as e:
        print(name,"ERR",e)
print()
res.sort(reverse=True)
print("RANKING by brightness-trajectory correlation:")
for corr,name,msv,mbv in res: print(f"  {name:<15} {corr:.3f}")
EOF

